    enableTotp: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description 6-digit TOTP code from authenticator app. Omit to start enrollment; include to verify & enable. */
                    code?: string | null;
                };
            };
        };
        responses: {
            /**
             * @description Response shape depends on the request. Without `code`: returns
             *     the QR code SVG and manual key. With `code`: returns the 10
             *     recovery codes. The frontend distinguishes the two by checking
             *     which fields are present in `data`.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["TotpEnableStartResponse"] | components["schemas"]["TotpEnableVerifyResponse"];
                };
            };
            /** @description Not authenticated. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /**
             * @description Validation error. Returned when:
             *     - `code` is present but is not a valid 6-digit TOTP code
             *     - the pending secret has expired (session timeout)
             *     - the code does not match the pending secret
             */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ValidationErrorResponse"];
                };
            };
        };
    };
